    /* ---------- navigation ---------- */
    private void wireNavigation470(){
        LinearLayout nav=bottom();if(nav==null)return;
        for(int i=0;i<nav.getChildCount();i++){
            View v=nav.getChildAt(i);
            if("v41_settings".equals(String.valueOf(v.getTag()))){v.setOnClickListener(x->showSettings470());continue;}
            String lab=findNavLabel(v);
            if(lab==null)continue;
            if(isSavedLabel(lab))v.setOnClickListener(x->showSaved470());
            else if(isCatalogLabel(lab))v.setOnClickListener(x->showCatalog470());
        }
        wireHomeTiles470(findViewById(android.R.id.content));
    }
