    /* ---------- catalog ---------- */
    private Set<String> favorites(){return new HashSet<>(settings().getStringSet("favorite_items",new HashSet<>()));}
    private void setFavorite(String n,boolean on){Set<String>s=favorites();if(on)s.add(n);else s.remove(n);settings().edit().putStringSet("favorite_items",s).apply();}
    private ArrayList<String> recent(){ArrayList<String> a=new ArrayList<>();String raw=settings().getString("recent_items","");if(!raw.isEmpty())for(String x:raw.split("\u001E"))if(!x.isEmpty()&&!a.contains(x))a.add(x);return a;}
    private void addRecent(String n){ArrayList<String>a=recent();a.remove(n);a.add(0,n);while(a.size()>12)a.remove(a.size()-1);settings().edit().putString("recent_items",TextUtils.join("\u001E",a)).apply();}
    private int recentIndex(String n){int i=recent().indexOf(n);return i<0?999:i;}
    private String groupLabel(String k){switch(k){case"RECENT":return tx("Recent","الأخيرة","دوایین");case"FAVORITES":return tx("Favorites","المفضلة","دڵخواز");case"ALL":return tx("All","الكل","هەموو");case"PANELS":return tx("Panels","الألواح","پانێڵ");case"HYBRID":return tx("Hybrid Inverters","إنفرترات هجينة","ئینڤێرتەری هایبرید");case"ONGRID":return tx("On-Grid","أون كريد","ئۆن‌گرید");case"PUMP":return tx("Pump","مضخات","پەمپ");case"BATTERY":return tx("Batteries","البطاريات","باتری");case"STRUCTURE":return tx("Structures","الهياكل","هەیکەل");case"CABLE":return tx("Cables","الكيبلات","کەیبڵ");case"PROTECTION":return tx("Protection","الحماية","پاراستن");case"INSTALL":return tx("Install/Delivery","تركيب/نقل","دامەزراندن/گواستنەوە");default:return tx("Other","أخرى","هیتر");}}
    private String groupOf(OfferStudioActivity.Product p){String c=(p.category==null?"":p.category).toLowerCase(Locale.ROOT),n=(p.name==null?"":p.name).toLowerCase(Locale.ROOT);if(c.contains("panel"))return"PANELS";if(n.contains("pump")||n.contains("lar100"))return"PUMP";if(n.contains("on-grid")||n.contains("on grid")||n.contains("ongrid"))return"ONGRID";if(c.contains("inverter")||n.contains("inverter"))return"HYBRID";if(c.contains("battery")||n.contains("battery")||n.contains("bms"))return"BATTERY";if(c.contains("structure")||n.contains("structure")||n.contains("rack"))return"STRUCTURE";if(n.contains("cable")||n.contains("connector"))return"CABLE";if(c.contains("installation")||c.contains("delivery")||n.contains("installation")||n.contains("transport")||n.contains("delivery")||n.contains("civil")||n.contains("maintenance"))return"INSTALL";if(c.contains("accessor")||c.contains("earthing")||c.contains("lightning")||n.contains("breaker")||n.contains("spd")||n.contains("combiner")||n.contains("ats")||n.contains("meter")||n.contains("zero export"))return"PROTECTION";return"OTHER";}
    private boolean matchGroup(OfferStudioActivity.Product p,String g){if(g.equals("ALL"))return true;if(g.equals("FAVORITES"))return favorites().contains(p.name);if(g.equals("RECENT"))return recent().contains(p.name);return g.equals(groupOf(p));}
