    private String safeFile(String s){if(s==null)return"";return s.trim().replaceAll("[^\\p{L}\\p{N}_-]+","_").replaceAll("_+","_").replaceAll("^_|_$","");}
    private String baseFileName(){OfferStudioActivity.Draft d=draft();String client=safeFile(d==null?"":d.client),cap=safeFile(d==null?"":d.capacity),date=safeFile(d==null?"":d.date);return "OrganizerForm_"+(client.isEmpty()?"Client":client)+(cap.isEmpty()?"":"_"+cap)+(date.isEmpty()?"":"_"+date);}
    private String formTitle(){String x=settings().getString("form_title","").trim();return x.isEmpty()?tx("Organizer Preliminary Solar Form","استمارة أولية للمنظومة الشمسية","فۆرمی سەرەتایی سیستەمی خۆرەوی"):x;}
    private File buildPdf470(){OfferStudioActivity.Draft d=draft();if(d==null)return null;try{File dir=getExternalFilesDir(Environment.DIRECTORY_DOCUMENTS);if(dir==null)return null;dir.mkdirs();File file=new File(dir,baseFileName()+".pdf");PdfDocument doc=new PdfDocument();Writer470 w=new Writer470(doc);w.newPage();w.header();w.section(tx("CLIENT","العميل","کڕیار"),108);w.row(tx("Client","العميل","کڕیار"),dash(d.client));w.row(tx("Phone","رقم الهاتف","ژمارەی تەلەفۆن"),dash(d.phone));w.row(tx("Location","الموقع","شوێن"),dash(d.location));w.row(tx("Date","التاريخ","بەروار"),dash(d.date));w.section(tx("SYSTEM","المنظومة","سیستەم"),81);w.row(tx("Type","النوع","جۆر"),dash(d.system));w.row(tx("Capacity","السعة","توانا"),dash(d.capacity));w.row(tx("Phase","الطور","فاز"),dash(d.phase));String itemsTitle=tx("REQUIRED ITEMS","المواد المطلوبة","ماددە پێویستەکان");w.section(itemsTitle,80);w.itemHeader();for(OfferStudioActivity.LineItem i:d.items)w.item(i,itemsTitle);if(showPrices()&&showTotal())w.big(tx("Estimated Total: ","المجموع التقديري: ","کۆی خەمڵاندراو: ")+money(grandTotal()),Color.rgb(20,153,112));if(showOrganizer()){w.section(tx("ORGANIZER DETAILS","بيانات المنظم","زانیاری ڕێکخەر"),108);w.row(tx("Installation","التركيب","دامەزراندن"),d.installation?tx("Included","مشمول","ناوخۆکراوە"):tx("Not included","غير مشمول","ناوخۆنەکراوە"));w.row(tx("Transport","النقل","گواستنەوە"),d.transport?tx("Included","مشمول","ناوخۆکراوە"):tx("Not included","غير مشمول","ناوخۆنەکراوە"));w.row(tx("Organizer","منظم الكشف","ڕێکخەر"),dash(d.organizer));w.row(tx("Included photos","الصور المضمنة","وێنە ناوخۆکراوەکان"),String.valueOf(includedPhotos().size()));}if(showNotes()&&!empty(d.notes)){String noteTitle=tx("LOAD / NOTES","التحميل / الملاحظات","بار / تێبینی");int noteHeight=w.measureParagraph(d.notes);w.section(noteTitle,noteHeight);w.paragraph(d.notes,noteTitle);}w.finish();ArrayList<String> ph=includedPhotos();for(int i=0;i<ph.size();i++){Bitmap bm=decodeImage(Uri.parse(ph.get(i)),1400);if(bm==null)continue;w.newPage();w.smallHeader(tx("Site Photo ","صورة الموقع ","وێنەی شوێن ")+(i+1));float scale=Math.min(500f/bm.getWidth(),680f/bm.getHeight());int nw=(int)(bm.getWidth()*scale),nh=(int)(bm.getHeight()*scale),left=(595-nw)/2,top=92;w.canvas.drawBitmap(bm,null,new Rect(left,top,left+nw,top+nh),null);w.finish();bm.recycle();}FileOutputStream out=new FileOutputStream(file);doc.writeTo(out);out.close();doc.close();return file;}catch(Exception e){Toast.makeText(this,tx("PDF error: ","خطأ PDF: ","هەڵەی PDF: ")+e.getMessage(),Toast.LENGTH_LONG).show();return null;}}
    private File buildJson470(File pdf){OfferStudioActivity.Draft d=draft();if(d==null||pdf==null)return null;try{JSONObject j=d.json();j.put("form_type","organizer_preliminary_solar_form");j.put("estimated_total",grandTotal().toPlainString());j.put("currency",currency());j.put("company",settings().getString("company_name","Infinity Green Power"));j.put("form_title",formTitle());JSONArray ph=new JSONArray();for(String u:includedPhotos())ph.put(u);j.put("included_photos",ph);File f=new File(pdf.getParentFile(),baseFileName()+".json");FileOutputStream out=new FileOutputStream(f);out.write(j.toString(2).getBytes("UTF-8"));out.close();return f;}catch(Exception e){return null;}}
